{
  "items": [
    {
      "name": "Matrix.det_eq_zero_of_not_linearIndependent_cols",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {m : Type u_1} [inst : DecidableEq m] [inst_1 : Fintype m] {R : Type v} [inst_2 : CommRing R] [IsDomain R]\n  {A : Matrix m m R}, (¬LinearIndependent R fun i => A.transpose i) → A.det = 0"
    },
    {
      "name": "Matrix.det_eq_zero_of_not_linearIndependent_rows",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {m : Type u_1} [inst : DecidableEq m] [inst_1 : Fintype m] {R : Type v} [inst_2 : CommRing R] [IsDomain R]\n  {A : Matrix m m R}, (¬LinearIndependent R fun i => A i) → A.det = 0"
    },
    {
      "name": "LinearMap.det_restrictScalars",
      "module_name": "Mathlib.RingTheory.Norm.Transitivity",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} {A : Type u_3} [inst : CommRing R] [inst_1 : CommRing S] [inst_2 : Algebra R S]\n  [Module.Free R S] [inst_4 : AddCommGroup A] [inst_5 : Module R A] [inst_6 : Module S A] [inst_7 : IsScalarTower R S A]\n  [Module.Free S A] {f : A →ₗ[S] A}, LinearMap.det (↑R f) = (Algebra.norm R) (LinearMap.det f)"
    },
    {
      "name": "LinearMap.det_eq_det_mul_det",
      "module_name": "Mathlib.LinearAlgebra.Determinant",
      "kind": "theorem",
      "type": "∀ {R : Type u_6} {V : Type u_7} [inst : CommRing R] [inst_1 : AddCommGroup V] [inst_2 : Module R V] [Module.Finite R V]\n  (W : Submodule R V) [Module.Free R ↥W] [Module.Finite R ↥W] [Module.Free R (V ⧸ W)] (e : V →ₗ[R] V)\n  (he : W ≤ Submodule.comap e W), LinearMap.det e = LinearMap.det (e.restrict he) * LinearMap.det (W.mapQ W e he)"
    },
    {
      "name": "Matrix.gram_apply",
      "module_name": "Mathlib.Analysis.InnerProductSpace.GramMatrix",
      "kind": "theorem",
      "type": "∀ {E : Type u_1} {n : Type u_2} {𝕜 : Type u_4} [inst : Inner 𝕜 E] (v : n → E) (i j : n),\n  Matrix.gram 𝕜 v i j = inner 𝕜 (v i) (v j)"
    },
    {
      "name": "exteriorPower.alternatingMapToDual_apply_ιMulti",
      "module_name": "Mathlib.LinearAlgebra.ExteriorPower.Pairing",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommRing R] [inst_1 : AddCommGroup M] [inst_2 : Module R M] {n : ℕ}\n  (f : Fin n → Module.Dual R M) (v : Fin n → M),\n  ((exteriorPower.alternatingMapToDual R M n) f) ((exteriorPower.ιMulti R n) v) = (Matrix.of fun i j => (f j) (v i)).det"
    }
  ]
}

